import ast
import re
from .models import Trace


def _sanitize_identifier(raw: str) -> str:
    cleaned = re.sub(r"[^a-zA-Z0-9_]", "_", raw)
    if not cleaned or cleaned[0].isdigit():
        cleaned = f"t_{cleaned}"
    return cleaned


def generate_pytest_code(trace: Trace) -> str:
    failed = trace.failed_steps
    if not failed:
        raise ValueError(f"Trace '{trace.trace_id}' contains no failed steps to generate tests for.")

    safe_trace_id = _sanitize_identifier(trace.trace_id)

    lines = [
        "# Auto-generated by failsafe. DO NOT EDIT MANUALLY.",
        f"# Source Trace ID: {trace.trace_id} (Agent Version: {trace.agent_version})",
        "import pytest",
        "from typing import Any",
        "",
        "",
        "class RecordedToolFailure(RuntimeError):",
        "    def __init__(self, tool_name: str, error_type: str, message: str):",
        "        self.tool_name = tool_name",
        "        self.error_type = error_type",
        "        self.message = message",
        "        super().__init__(f'{tool_name} failed with {error_type}: {message}')",
        "",
        "",
        "class ToolReplayStub:",
        "    \"\"\"Deterministic stub that replays recorded tool failures without executing live code.\"\"\"",
        "    def __init__(self, tool_name: str, expected_args: dict[str, Any], error_type: str, error_msg: str):",
        "        self.tool_name = tool_name",
        "        self.expected_args = expected_args",
        "        self.error_type = error_type",
        "        self.error_msg = error_msg",
        "",
        "    def execute(self, **kwargs: Any) -> Any:",
        "        if kwargs != self.expected_args:",
        "            raise AssertionError(",
        "                f'Non-deterministic call to {self.tool_name}.\\n'",
        "                f'Expected: {self.expected_args!r}\\nGot:      {kwargs!r}'",
        "            )",
        "        raise RecordedToolFailure(self.tool_name, self.error_type, self.error_msg)",
        "",
    ]

    for step in failed:
        fn_name = f"test_trace_{safe_trace_id}_step_{step.step_id}_{step.tool_name}"
        lines.extend([
            "",
            f"def {fn_name}() -> None:",
            f"    \"\"\"Reproduces failure in step {step.step_id} ({step.tool_name}).\"\"\"",
            f"    recorded_args = {repr(step.arguments)}",
            f"    stub = ToolReplayStub(",
            f"        tool_name={repr(step.tool_name)},",
            f"        expected_args=recorded_args,",
            f"        error_type={repr(step.error_type)},",
            f"        error_msg={repr(step.error_message)},",
            f"    )",
            "",
            "    # Verify the stub deterministically raises the exact recorded failure.",
            "    # Replace `stub.execute` with your agent's tool wrapper to verify error handling.",
            "    with pytest.raises(RecordedToolFailure) as exc_info:",
            "        stub.execute(**recorded_args)",
            "",
            f"    assert exc_info.value.error_type == {repr(step.error_type)}",
            f"    assert exc_info.value.message == {repr(step.error_message)}",
            "",
        ])

    source_code = "\n".join(lines)

    # Safety check: verify generated code is syntactically valid Python
    ast.parse(source_code)
    return source_code